function strangePrinter(s) {
  const n = s.length;
  const dp = Array.from({ length: n }, () => new Array(n).fill(0));

  for (let left = n - 1; left >= 0; left--) {
    dp[left][left] = 1;
    for (let right = left + 1; right < n; right++) {
      dp[left][right] = dp[left][right - 1] + 1;
      for (let mid = left; mid < right; mid++) {
        if (s[mid] !== s[right]) {
          continue;
        }
        const inside = mid + 1 <= right - 1 ? dp[mid + 1][right - 1] : 0;
        dp[left][right] = Math.min(dp[left][right], dp[left][mid] + inside);
      }
    }
  }
  return dp[0][n - 1];
}

