function strangePrinter(s) {
  // Undo strokes from the last one backwards. covered[i] means a later stroke already explains position i.
  // A stroke can be undone when every uncovered position in its range shows its letter; widening it as far
  // as that rule allows never hurts. Iterative deepening tries budgets 1, 2, ... so the first success is optimal.
  const n = s.length;
  const covered = new Array(n).fill(false);
  let failed = new Map();
  const search = (budget) => {
    const showing = new Set();
    for (let i = 0; i < n; i++) if (!covered[i]) showing.add(s[i]);
    if (showing.size === 0) return true;
    if (showing.size > budget) return false;
    const key = covered.map(c => (c ? '1' : '0')).join('');
    if ((failed.get(key) ?? -1) >= budget) return false;
    for (let p = 0; p < n; p++) {
      if (covered[p]) continue;
      let l = p;
      while (l > 0 && (covered[l - 1] || s[l - 1] === s[p])) l--;
      let r = p;
      while (r < n - 1 && (covered[r + 1] || s[r + 1] === s[p])) r++;
      let firstOpen = l;
      while (covered[firstOpen]) firstOpen++;
      if (firstOpen < p) continue; // the same range was already tried from an earlier position
      const saved = covered.slice(l, r + 1);
      for (let i = l; i <= r; i++) covered[i] = true;
      const done = search(budget - 1);
      for (let i = l; i <= r; i++) covered[i] = saved[i - l];
      if (done) return true;
    }
    if (failed.size > 50000) failed = new Map();
    failed.set(key, budget);
    return false;
  };
  for (let budget = 1; ; budget++) if (search(budget)) return budget;
}

