function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 9);
    const k = 1 + Math.floor(rand() * 3);
    let s = '';
    for (let i = 0; i < n; i++) s += letters[Math.floor(rand() * k)];
    return [s];
  }
  const n = 80 + Math.floor(rand() * 21);
  const k = 2 + Math.floor(rand() * 25);
  let s = '';
  for (let i = 0; i < n; i++) s += letters[Math.floor(rand() * k)];
  return [s];
}
